// Deduplicate by name
const seen = new Set();
const unique = entities.filter(e => {
  if (seen.has(e.name)) return false;
  seen.add(e.name);
  return true;
});

console.log(`Seeding ${unique.length} entities...`);

let inserted = 0;
let skipped = 0;

for (const e of unique) {
  try {
    await conn.execute(
      `INSERT IGNORE INTO ai_agent_entities (name, type, tier, country, sector, aliases, is_active)
       VALUES (?, ?, ?, ?, ?, ?, 1)`,
      [e.name, e.type, e.tier, e.country || null, e.sector || null, JSON.stringify(e.aliases || [])]
    );
    inserted++;
  } catch (err) {
    console.error(`Error inserting ${e.name}:`, err.message);
    skipped++;
  }
}

await conn.end();
console.log(`Done! Inserted: ${inserted}, Skipped: ${skipped}`);
